    total = 0
    for c in coeffs:
        total = total * x + c
    return total

def ends(n, a):
    if n == 0:
        return "flat on both ends"
    if n % 2 == 0 and a > 0:
        return "up on the left, up on the right"
    if n % 2 == 0:
        return "down on the left, down on the right"
    if a > 0:
        return "down on the left, up on the right"
    return "up on the left, down on the right"

cases = [
    ("odd degree, positive", [2, -5, 0, 1]),
    ("even degree, negative", [-3, 1, 0, 0, 7]),
    ("the trap: a big coefficient", [1, -100, 0, 0]),
    ("a line", [-2, 3]),
    ("a word problem, profit", [-1, 12, -20, 0]),
]
for label, coeffs in cases:
    n = len(coeffs) - 1
    a = coeffs[0]
    print(f"{label}: coefficients {coeffs}")
    print(f"  step 1: degree {n}, leading term {a}x^{n}")
    print(f"  step 2: {ends(n, a)}")
    for x in [20, 1000, 10 ** 6]:
        ratio = value(coeffs, x) / (a * x ** n)
        print(f"  x = {x}: p(x) / ({a}x^{n}) = {ratio:.4f}")

