from fractions import Fraction

def value(coeffs, x):
    # multiply by x and add the next coefficient, the steps of synthetic division
    total = 0
    for c in coeffs:
        total = total * x + c
    return total

def divide(coeffs, c):
    q = []
    carry = 0
    for i in range(len(coeffs)):
        carry = carry * c + coeffs[i]
        if i < len(coeffs) - 1:
            q.append(carry)
    return q, carry

def sign(v):
    if v > 0:
        return "+"
    if v < 0:
        return "-"
    return "0"

cases = [
    ("a simple zero", [1, -2, -5, 6], 1),
    ("a double zero", [1, 0, -3, -2], -1),
    ("a triple zero", [1, -3, 3, -1], 1),
    ("not a zero", [1, -2, -5, 6], 2),
    ("a word problem, the box", [4, -48, 144, 0], 6),
]
for label, coeffs, c in cases:
    print(f"{label}: coefficients {coeffs}, c = {c}")
    m = 0
    q, r = divide(coeffs, c)
    print(f"  divide by x - ({c}): quotient {q}, remainder {r}")
    while r == 0:
        m = m + 1
        q, r = divide(q, c)
        print(f"  divide again: quotient {q}, remainder {r}")
    left = value(coeffs, c - Fraction(1, 10))
    right = value(coeffs, c + Fraction(1, 10))
    if m == 0:
        print(f"  remainder {r} is not 0, so {c} is not a zero")
    elif m % 2 == 1:
        print(f"  multiplicity {m}, odd: crosses")
    else:
        print(f"  multiplicity {m}, even: touches")
    print(f"  check: signs just left and right of {c} are {sign(left)} and {sign(right)}")

