from fractions import Fraction

def p(a, zeros, x):
    total = a
    for r, m in zeros:
        total = total * (x - r) ** m
    return total

def sign(v):
    if v > 0:
        return "positive"
    return "negative"

cases = [
    ("three simple zeros", 1, [(-2, 1), (1, 1), (3, 1)]),
    ("a touch", -1, [(-2, 1), (1, 2)]),
    ("even degree", 1, [(-2, 1), (-1, 1), (1, 1), (2, 1)]),
    ("a zero at 0", 1, [(-2, 1), (0, 1), (2, 1)]),
    ("a word problem, the box", 4, [(0, 1), (6, 2)]),
]
for label, a, zeros in cases:
    n = 0
    for r, m in zeros:
        n = n + m
    print(f"{label}: a = {a}, zeros with multiplicities {zeros}")
    if n % 2 == 0 and a > 0:
        print(f"  ends: degree {n} even, a > 0: up on both ends")
    elif n % 2 == 0:
        print(f"  ends: degree {n} even, a < 0: down on both ends")
    elif a > 0:
        print(f"  ends: degree {n} odd, a > 0: down on the left, up on the right")
    else:
        print(f"  ends: degree {n} odd, a < 0: up on the left, down on the right")
    print(f"  y-intercept: p(0) = {p(a, zeros, 0)}")
    first = zeros[0][0]
    last = zeros[len(zeros) - 1][0]
    print(f"  x < {first}: test {first - 1}, {sign(p(a, zeros, first - 1))}")
    for i in range(len(zeros) - 1):
        lo = zeros[i][0]
        hi = zeros[i + 1][0]
        t = Fraction(lo + hi, 2)
        print(f"  {lo} < x < {hi}: test {t}, {sign(p(a, zeros, t))}")
    print(f"  x > {last}: test {last + 1}, {sign(p(a, zeros, last + 1))}")

