from fractions import Fraction

def p(a, zeros, x):
    total = a
    for r, m in zeros:
        total = total * (x - r) ** m
    return total

def sign(v):
    if v > 0:
        return "positive"
    return "negative"

n = int(input())
for i in range(n):
    a = int(input())
    k = int(input())
    zeros = []
    for j in range(k):
        r = int(input())
        m = int(input())
        zeros.append((r, m))
    degree = 0
    for r, m in zeros:
        degree = degree + m
    if degree % 2 == 0 and a > 0:
        print("ends: up on the left, up on the right")
    elif degree % 2 == 0:
        print("ends: down on the left, down on the right")
    elif a > 0:
        print("ends: down on the left, up on the right")
    else:
        print("ends: up on the left, down on the right")
    print(f"y-intercept: {p(a, zeros, 0)}")
    first = zeros[0][0]
    last = zeros[k - 1][0]
    print(f"x < {first}: {sign(p(a, zeros, first - 1))}")
    for j in range(k - 1):
        lo = zeros[j][0]
        hi = zeros[j + 1][0]
        print(f"{lo} < x < {hi}: {sign(p(a, zeros, Fraction(lo + hi, 2)))}")
    print(f"x > {last}: {sign(p(a, zeros, last + 1))}")
